    var elNo = document.getElementById('podNo'), elT = document.getElementById('podTitle');
    var elCur = document.getElementById('podCur'), elDur = document.getElementById('podDur');
    var prog = document.getElementById('podProg'), bar = document.getElementById('podBar');
    var lkEl = document.getElementById('podLk');
    var cur = 0;
    function fmt(s){ if (!isFinite(s)) return '0:00'; s = Math.floor(s); return Math.floor(s/60) + ':' + ('0'+(s%60)).slice(-2); }
    q.innerHTML = EPS.map(function(e, i){
      return '<button class="pod-ep' + (i === 0 ? ' on' : '') + '" type="button" data-i="' + i + '">'
        + '<span class="pod-ep-n">' + e.n + '</span>'
        + '<span class="pod-ep-t">' + e.t.replace(/&/g,'&amp;').replace(/</g,'&lt;') + '</span>'
        + '<span class="pod-ep-d">' + e.d + '</span></button>';
    }).join('');
    function load(i, play){
      cur = i; var e = EPS[i];
      audio.src = e.u;
      elNo.textContent = e.n ? ('Episode ' + e.n) : 'Le Random';
      elT.textContent = e.t; elDur.textContent = e.d; elCur.textContent = '0:00';
      prog.style.width = '0%';
      if (lkEl) lkEl.innerHTML = (window.__lrPodLinks ? window.__lrPodLinks(e.n) : '');
      [].forEach.call(q.children, function(c, j){ c.classList.toggle('on', j === i); });
      if (play) audio.play().catch(function(){});
    }
    q.addEventListener('click', function(ev){
      var tx = ev.target.closest('.pod-tx');
      if (tx) { ev.stopPropagation(); location.hash = '#pod=' + tx.dataset.n; return; }
      var b = ev.target.closest('.pod-ep'); if (!b) return;
      load(+b.dataset.i, true);
    });
    function seekBy(d){
      if (!audio.src) { load(cur, false); }
      var go = function(){ audio.currentTime = Math.max(0, Math.min((audio.duration || 1e9), audio.currentTime + d)); };
      if (audio.readyState >= 1) go();
      else { audio.addEventListener('loadedmetadata', go, { once: true }); audio.load(); }
    }
    document.getElementById('podB15').addEventListener('click', function(){ seekBy(-15); });
    document.getElementById('podF15').addEventListener('click', function(){ seekBy(15); });
    var RATES = [1, 1.25, 1.5, 1.75, 2], ri = 0, rateBtn = document.getElementById('podRate');
    rateBtn.addEventListener('click', function(){
      ri = (ri + 1) % RATES.length; audio.playbackRate = RATES[ri]; rateBtn.innerHTML = RATES[ri] + '&#215;';
    });
    audio.addEventListener('play', function(){ audio.playbackRate = RATES[ri]; });
    fetch(LRWB+'pod/roll.json')
      .then(function(r){ return r.json(); }).then(function(eps){
        var tx = {}; eps.forEach(function(e){ if (e.tx) tx[e.n] = true; });
        [].forEach.call(q.querySelectorAll('.pod-ep'), function(row){
          var n = parseInt((row.querySelector('.pod-ep-n') || {}).textContent, 10);
          if (tx[n] && !row.querySelector('.pod-tx')) {
            var s = document.createElement('span');
            s.className = 'pod-tx'; s.dataset.n = n; s.textContent = 'Transcript';
            var d = row.querySelector('.pod-ep-d');
            /* audit 20 Sep: .pod-ep-d can be re-parented into a sub-wrapper, and insertBefore then
               throws NotFoundError, killing the whole badge pass. Insert only if it is still a child. */
            if (d && d.parentNode === row) row.insertBefore(s, d); else row.appendChild(s);
          }
        });
      }).catch(function(){});
    btn.addEventListener('click', function(){
      if (audio.paused) { if (!audio.src) load(cur, true); else audio.play().catch(function(){}); }
      else audio.pause();
    });
    audio.addEventListener('play',  function(){ btn.classList.add('playing'); btn.setAttribute('aria-label','Pause episode'); });
    audio.addEventListener('pause', function(){ btn.classList.remove('playing'); btn.setAttribute('aria-label','Play episode'); });
    audio.addEventListener('timeupdate', function(){
      if (!audio.duration) return;
      prog.style.width = (audio.currentTime / audio.duration * 100) + '%';
      elCur.textContent = fmt(audio.currentTime);
    });
    audio.addEventListener('loadedmetadata', function(){ if (audio.duration) elDur.textContent = fmt(audio.duration); });
    audio.addEventListener('ended', function(){ if (cur + 1 < EPS.length) load(cur + 1, true); });
    bar.addEventListener('click', function(ev){
      if (!audio.duration) return;
      var r = bar.getBoundingClientRect();
      audio.currentTime = ((ev.clientX - r.left) / r.width) * audio.duration;
    });
    load(0, false);
    /* the podcast plate mirrors the film plate's height exactly, at every width */
    var film = document.querySelector('.media-frame.is-video');
    function syncPod(){
      if (!film) return;
      var p = document.querySelector('.pod');
      if (!p) return;
      /* lr-pod-links: below 900px the plate sits under the film, not beside it, so the
         mirror aligns nothing and the queue pays for every pixel the meta column takes.
         Release it and let the css give the queue a whole-row height instead. */
      if (window.innerWidth <= 900) { p.style.height = ''; p.style.flex = ''; return; }
      var hgt = film.getBoundingClientRect().height;
      if (hgt > 120) { p.style.height = hgt + 'px'; p.style.flex = '0 0 auto'; }
    }
    window.addEventListener('resize', syncPod);
    if (window.ResizeObserver && film) new ResizeObserver(syncPod).observe(film);
