  /* ---- YouTube: a facade, so a blocked embed can never show an error ----
     Served over http(s) the real player is injected on click; from file:// (or
     wherever YouTube refuses the origin) we hand off to youtube.com instead. ---- */
  (function(){
    var frame = document.getElementById('yt-frame');
    if (!frame) return;
    var id = frame.getAttribute('data-id');
    var thumb = document.getElementById('yt-thumb');
    if (thumb) {
      thumb.addEventListener('error', function once(){
        thumb.removeEventListener('error', once);
        thumb.src = 'https://i.ytimg.com/vi/' + id + '/hqdefault.jpg';
      });
    }
    var btn = frame.querySelector('.yt-facade');
    btn.addEventListener('click', function(){
      if (location.protocol === 'http:' || location.protocol === 'https:') {
        var f = document.createElement('iframe');
        f.src = 'https://www.youtube-nocookie.com/embed/' + id + '?rel=0&autoplay=1';
        f.title = 'AI Psychosis Summit with Peter Bauman';
        f.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; picture-in-picture';
        f.setAttribute('allowfullscreen', '');
        frame.innerHTML = '';
        frame.appendChild(f);
      } else {
        window.open('https://www.youtube.com/watch?v=' + id, '_blank');
      }
    });
  })();

  /* ---- sticky bar: show its rule only after scrolling ---- */
  (function(){
    var bar = document.getElementById('topbar'); if (!bar) return;
    var tick = false;
    function upd(){ bar.classList.toggle('stuck', window.scrollY > 6); tick = false; }
    addEventListener('scroll', function(){
      if (!tick) { tick = true; requestAnimationFrame(upd); }
    }, {passive:true});
    upd();
  })();

  /* ---- dossiers: hovering a part shows that piece's cover on the plate ---- */
  [].forEach.call(document.querySelectorAll('.dz'), function(dz){
    var front = dz.querySelector('.dz-front');
    var parts = [].slice.call(dz.querySelectorAll('.dz-part'));
    if (!front || !parts.length) return;
    var def = front.getAttribute('data-default');
    var token = 0;
    function show(src){
      if (front.dataset.cur === src) return;
      var mine = ++token;
      var pre = new Image();
      pre.onload = function(){
        if (mine !== token) return;                 /* a newer hover won */
        front.style.backgroundImage = 'url("' + src + '")';
        front.dataset.cur = src;
        front.style.opacity = '1';
      };
      front.style.opacity = '.3';
      pre.src = src;
    }
    parts.forEach(function(p){
      p.addEventListener('mouseenter', function(){
        parts.forEach(function(x){ x.classList.toggle('on', x === p); });
        show(p.getAttribute('data-img'));
      });
    });
    dz.addEventListener('mouseleave', function(){
      parts.forEach(function(x){ x.classList.remove('on'); });
      show(def);
    });
  });

  /* ---- timeline: rotate the moment by the day of the year ---- */
  var MOMENTS = [["1960", "Kurd Alsleben and Cord Passow make analog computer drawings", "Artist Kurd Alsleben in collaboration with physicist Cord Passow used an analogue computer (EAI 231 R) in Hamburg to create parametric generative art. The analog computer, combined with a mechanical drawing mechanism, produced graphical works of waves and lines based on the changing results of an equation."], ["1960", "Vera Molnár co-founds the Centre de Recherche d’Art Visuel", "Playing a significant role in the development of Kinetic and Op Art, the Parisian collective aimed to explore the relationship between art, science and technology to create works that empirically engaged with new materials."], ["1960", "The first recording of computer generated music", "The first recording of computer generated music, Music from Mathematics, created by John R. Pierce and Max Mathews at Bell Labs."], ["1960", "William Fetter creates the first computer graphics", "At the Wichita Branch of the Military Aircraft Systems Division of Boeing, William Fetter coined the term “computer graphics” to refer to his plotter drawings."], ["1960", "John McCarthy introduces LISP", "John McCarthy at MIT introduced the programming language LISP, which would underpin decades of work in artificial intelligence."]];
  (function(){
    var now = new Date();
    var day = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);
    var m = MOMENTS[day % MOMENTS.length];
    var y = document.getElementById('tl-year'), t = document.getElementById('tl-title'), b = document.getElementById('tl-body');
    if (y && m) { y.textContent = m[0]; t.textContent = m[1]; b.textContent = m[2]; }
  })();

  /* ---- the framework: four parts, one panel ---- */
  var fwTabs = [].slice.call(document.querySelectorAll('.fw-tab'));
