  function harvestRows(){
    var out = {};
    [].forEach.call(document.querySelectorAll('#register .rg-row:not(.rg-pod)'), function(r){
      var href = r.getAttribute('href') || '';
      var m2 = href.match(/\/editorial\/([a-z0-9-]+)/);
      if (!m2) return;
      out[m2[1]] = { href: href, no: (r.querySelector('.rg-no') || {}).textContent || '',
        t: (function(){ var t = r.querySelector('.rg-t'); return t ? (t.childNodes[0] ? t.childNodes[0].nodeValue : t.textContent).trim() : ''; })() };
    });
    return out;
  }
  function historyDeal(seed){
    var eras = [].slice.call(document.querySelectorAll('#history .era'));
    if (!eras.length) return;
    var rows = harvestRows();
    var banks = [[], [], [], []];
    Object.keys(ERAS).forEach(function(s){ if (rows[s]) banks[ERAS[s]].push(rows[s]); });
    eras.forEach(function(era, i){
      var bank = banks[i] || [];
      if (bank.length < 3) return;                    /* keep the curated column if the bank is thin */
      var rng = mul((seed | 0) ^ (0x415701 + i));
      var deck = bank.slice();
      for (var x = deck.length - 1; x > 0; x--){ var k = Math.floor(rng() * (x + 1)); var t2 = deck[x]; deck[x] = deck[k]; deck[k] = t2; }
      var picks = deck.slice(0, Math.min(6, deck.length));
      [].forEach.call(era.querySelectorAll('a.era-item'), function(el){ el.remove(); });
      picks.forEach(function(p){
        var a = document.createElement('a');
        a.className = 'era-item'; a.href = p.href;
        a.innerHTML = '<span class="n">' + p.no + '</span><span class="t"></span>';
        a.querySelector('.t').textContent = p.t;
        era.appendChild(a);
      });
    });
  }
  /* weighted shuffle: heavier items float up, never guaranteed (Efraimidis-Spirakis keys) */
  function weightedOrder(parent, sel, rng, weightOf){
    if (!parent) return;
    var kids = [].slice.call(parent.querySelectorAll(':scope > ' + sel));
    if (kids.length < 2) return;
    kids.map(function(el){ return { el: el, k: Math.pow(rng(), 1 / Math.max(1, weightOf(el))) }; })
      .sort(function(a, b2){ return b2.k - a.k; })
      .forEach(function(x){ parent.appendChild(x.el); });
  }
  function subjectsDeal(rng){
    [].forEach.call(document.querySelectorAll('#subjects .sx-col, #subjects [class*="sx-list"]'), function(col){
      weightedOrder(col, 'a, button', rng, function(el){
        var m2 = (el.textContent || '').match(/(\d+)/g);
        return m2 ? parseInt(m2[m2.length - 1], 10) : 1;
      });
    });
  }
  function contribsDefault(){
    var grid = document.querySelector('#contributors .cb-grid') ||
      (document.querySelector('#contributors .cb') || {}).parentElement;
    if (!grid) return;
    [].slice.call(grid.querySelectorAll(':scope > a.cb'))
      .map(function(el){
        var m2 = (el.querySelector('.cb-count') || { textContent: '' }).textContent.match(/(\d+)/);
        return { el: el, c: m2 ? parseInt(m2[1], 10) : 0,
          nm: (el.querySelector('.cb-name') || { textContent: '' }).textContent.trim() };
      })
      .sort(function(a, b2){ return b2.c - a.c || a.nm.localeCompare(b2.nm); })
      .forEach(function(x){ grid.appendChild(x.el); });
  }
  function contribsDeal(rng){
    var grid = document.querySelector('#contributors .cb-grid') ||
      (document.querySelector('#contributors .cb') || {}).parentElement;
    weightedOrder(grid, 'a.cb', rng, function(el){
      var m2 = (el.querySelector('.cb-count') || { textContent: '' }).textContent.match(/(\d+)/);
      var w = m2 ? parseInt(m2[1], 10) : 1;
      if (/Peter Bauman/.test((el.querySelector('.cb-name') || {}).textContent || '')) w = Math.min(w, 10);
      return w;
    });
  }
  var rcMode = 'chrono';
  function rcChrono(){
    var list = document.getElementById('rc-list'); if (!list) return;
    [].slice.call(list.querySelectorAll('.rc-item'))
      .sort(function(a, b){ return (+b.dataset.n || 0) - (+a.dataset.n || 0); })   /* chronological = newest first, the order the list starts in (Peter, 9 Sep) */
      .forEach(function(el){ list.appendChild(el); });
  }
  function deal(seed, isRoll){
    essaysDeal(mul((seed | 0) ^ 0xE55A75));
    popularDeal(mul((seed | 0) ^ 0x907A12));
    shuffleKids(document.querySelector('#readers .rd-grid'), 'article.reader', mul((seed | 0) ^ 0x4EAD34));
    historyDeal(seed);
    /* subjectsDeal disabled Sep 2: the grid is renderer-managed; reordering it live duplicated rows */
    if (isRoll) contribsDeal(mul((seed | 0) ^ 0xC0B71B));
    else contribsDefault();   /* boot: by appearances, then alphabetically (Peter, Sep 2) */
    if (isRoll) { shuffleKids(document.getElementById('rc-list'), 'a.rc-item', mul((seed | 0) ^ 0x1C7E11)); rcMode = 'standard'; rcBase = null; rcPressed(false); }   /* the die deals the list; the button sorts it newest first (Peter, 9 Sep) */
    else { rcChrono(); rcMode = 'chrono'; rcPressed(true); }
  }
  function edMini(seed){
    [].forEach.call(document.querySelectorAll('.zone-roll, .cur-roll'), function(btn){
      var tag = btn.previousElementSibling;
      if (!tag || !tag.classList || !tag.classList.contains('ed-mini')) tag = btn.parentNode.querySelector(':scope > .ed-mini') || tag;   /* native: a baked label one step further left (Contributors: label, A-Z, die) */
      if (!tag || !tag.classList || !tag.classList.contains('ed-mini')){
        tag = document.createElement('span'); tag.className = 'ed-mini';
        btn.parentNode.insertBefore(tag, btn);
      }
      tag.textContent = 'Edition \u2116' + String(seed).padStart(6, '0');
    });
  }
