(function(){
  /* ---------- lr-search-upcoming: the Upcoming calendar joins the search ---------- */
  try {
    var q = document.getElementById('rg-q'), head = document.getElementById('register-upcoming'), body = document.getElementById('up-rows'), shown = document.getElementById('up-shown');
    if (!q || !head || !body) return;
    var DATA = null, CAP = 40, MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    function load(cb){ if (DATA) { cb(); return; } fetch(LRWB + 'calendar.json').then(function(r){ return r.json(); }).then(function(d){ DATA = (d && d.items) || []; cb(); }).catch(function(){}); }
    function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;'); }
    function kind(k){ return k === 'event' ? 'Event' : (k === 'exhibition' ? 'Exhibition' : (k === 'deadline' ? 'Deadline' : 'Anniversary')); }
    function when(it){ if (!it.s) return ''; var p = it.s.split('-'); var d = parseInt(p[2], 10), m = MON[parseInt(p[1], 10) - 1] || ''; return (it.now ? 'Now' : (d + ' ' + m)); }
    function activeFilter(){ var on = document.querySelector('.rg-chip.on'); return on ? on.dataset.f : 'all'; }
    function render(){
      var s = (window.__lrwFold || function(x){ return String(x).toLowerCase(); })(q.value.trim()), f = activeFilter();
      if (!(s.length >= 2 && f === 'all')) { head.style.display = 'none'; body.innerHTML = ''; return; }
      load(function(){
        var today = new Date(); today.setHours(0,0,0,0);
        var hits = DATA.filter(function(it){
          if (it.e && new Date(it.e) < today) return false;
          var hay = (window.__lrwFold || function(x){ return String(x).toLowerCase(); })((it.t || '') + ' ' + (it.p || '') + ' ' + (it.v || '') + ' ' + (it.run || '') + ' ' + kind(it.k));
          return hay.indexOf(s) > -1;
        });
        head.style.display = hits.length ? '' : 'none';
        if (shown) shown.textContent = hits.length;
        body.innerHTML = hits.slice(0, CAP).map(function(it){
          return '<a class="tl-row up-row" href="#calendar" data-s="' + esc(it.s || '') + '"><span class="tl-y">' + esc(when(it)) + '</span>'
            + '<span class="tl-n">' + esc(it.t) + '</span><span class="tl-c">' + kind(it.k) + '</span>'
            + (it.p ? '<span class="tl-t">' + esc(it.p) + '</span>' : '') + '</a>';
        }).join('') + (hits.length > CAP ? '<div class="tl-more">' + (hits.length - CAP) + ' more upcoming entries match. Narrow the search to see them.</div>' : '');
        var empty = document.getElementById('rg-empty'); if (empty && hits.length) empty.style.display = 'none';
      });
    }
    q.addEventListener('input', render);
    document.addEventListener('click', function(e){
      if (e.target.closest('.rg-chip')) { setTimeout(render, 0); return; }
      var a = e.target.closest('.up-row'); if (!a) return;
      e.preventDefault();
      if (window.__lrwPlannerGoto && a.getAttribute('data-s')) window.__lrwPlannerGoto(a.getAttribute('data-s'));
      var cal = document.getElementById('calendar'); if (cal) { cal.scrollIntoView({ behavior: 'smooth', block: 'start' }); history.replaceState(null, '', location.pathname + location.search + '#calendar'); }
    });
  } catch (e) {}
})();
